\title{Degree-Zero Hochschild Homology of a Group Algebra is the Free Module on Conjugacy Classes}
\author{Aristotle}
\date{June 26, 2026}

\begin{document}

\begin{abstract}
Let $R$ be a commutative ring and $G$ a group. The degree-zero Hochschild
homology of the group algebra $R[G]$ is the quotient
$\HH_0(R[G]) = R[G]/[R[G],R[G]]$, where $[R[G],R[G]]$ is the $R$-submodule
generated by all additive commutators $xy - yx$. We prove an explicit
$R$-linear equivalence $\HH_0(R[G]) \simeq_R R[\Conj(G)]$, where $\Conj(G)$ is
the set of conjugacy classes of $G$ and $R[\Conj(G)]$ is the free $R$-module on
that set. The equivalence is induced by the canonical map sending a basis
element $g$ to its conjugacy class $[g]$, and its core is the identity
$[R[G],R[G]] = \ker(\toConj)$. Although classically stated for finite groups,
finiteness is unnecessary: the proof only sums over the finite support of a fixed
element, so the theorem holds for arbitrary $G$ and $R$. The finite case is a
corollary. All statements have been formally verified in Lean~4 on top of
Mathlib.
\end{abstract}

\maketitle

\section{Introduction}

Hochschild homology $\HH_\bullet(A)$ is a fundamental invariant of an associative
$R$-algebra $A$. Its degree-zero piece admits an elementary description:
\[ \HH_0(A) = A/[A,A], \]
the quotient of $A$ by the $R$-submodule $[A,A]$ generated by all additive
commutators $ab-ba$. This is the largest quotient of $A$ on which
multiplication-order becomes invisible, and it is the \emph{universal receptacle
for traces}: any $R$-linear $\tau : A \to V$ with $\tau(ab)=\tau(ba)$ factors
uniquely through $A \twoheadrightarrow \HH_0(A)$.

For a group algebra $A = R[G]$, folklore holds that $\HH_0(R[G])$ is free on the
conjugacy classes of $G$. We give a self-contained, formally verified proof and
make three points precise: (i) the equivalence is explicit, induced by the class
map $\toConj$; (ii) the single nontrivial input is the identification
$[R[G],R[G]] = \ker(\toConj)$ (Theorem~\ref{thm:eqker}); (iii) finiteness of $G$
is unnecessary (Theorem~\ref{thm:main}), the finite case being a corollary
(Corollary~\ref{cor:finite}).

\subsection{Relation to representation theory}
When $G$ is finite and $R=\mathbb{C}$, the number of conjugacy classes equals the
number of irreducible representations. Our theorem exhibits the conjugacy-class
count as the $R$-rank of $\HH_0(R[G])$, and explains why characters are class
functions: a character is a trace, hence factors through
$\HH_0(\mathbb{C}[G]) = \mathbb{C}[\Conj(G)]$.

\section{Preliminaries and notation}

Throughout, $R$ is a commutative ring and $G$ a group (no finiteness assumed
unless stated).

\begin{definition}[Group algebra]
The \emph{group algebra} $R[G]$ is the $R$-algebra of finitely supported
functions $G \to R$ (\texttt{MonoidAlgebra R G}). Its standard basis is
$\{\single g\,1 : g\in G\}$, where $\single g\,r$ takes value $r$ at $g$ and $0$
elsewhere. Multiplication is the convolution
\begin{equation}\label{eq:conv}
(\single a\,r)(\single b\,s) = \single (ab)\,(rs).
\end{equation}
Every $w \in R[G]$ is a finite sum $w = \sum_{g\in\supp(w)} \single g\,(w\,g)$.
\end{definition}

\begin{definition}[Conjugacy]
Elements $u,v \in G$ are \emph{conjugate}, $u \sim v$, if $v = c\,u\,c^{-1}$ for
some $c\in G$. The quotient set is $\Conj(G) = \ConjClasses G$, with class
$[g] = \mk(g)$. We use
\begin{equation}\label{eq:mkeq}
[u]=[v] \iff u\sim v.
\end{equation}
\end{definition}

\begin{definition}[Free module on conjugacy classes]
Write $R[\Conj(G)] = (\ConjClasses G \to_0 R)$ for the free $R$-module with basis
$\Conj(G)$.
\end{definition}

\begin{lemma}[Functorial change of index]\label{lem:func}
For $f : X \to Y$ there is an $R$-linear map $\lmapDomain f : (X\to_0 R) \to
(Y\to_0 R)$ with $\lmapDomain f\,(\single x\,r) = \single (f\,x)\,r$, and
$\mapDomain(f'\circ f) = \mapDomain f' \circ \mapDomain f$.
\end{lemma}

\section{Degree-zero Hochschild homology of $R[G]$}

\begin{definition}[Commutator submodule]
\[ [R[G],R[G]] := \spann_R\{\, z\in R[G] : \exists\, x,y,\ z = xy-yx \,\}. \]
\end{definition}

\begin{definition}[Degree-zero Hochschild homology]
$\HH_0(R[G]) := R[G]/[R[G],R[G]]$, the $R$-module quotient.
\end{definition}

\begin{proposition}[Universal trace property]\label{prop:univ}
If $\tau : R[G]\to V$ is $R$-linear with $\tau(xy)=\tau(yx)$ for all $x,y$, then
$\tau$ vanishes on $[R[G],R[G]]$ and factors uniquely through
$\pi : R[G]\twoheadrightarrow \HH_0(R[G])$.
\end{proposition}
\begin{proof}
$\tau(xy-yx)=0$, so each generator lies in $\ker\tau$; as $\ker\tau$ is a
submodule it contains the span. Factorization is the universal property of the
quotient.
\end{proof}

\section{The canonical class map}

\begin{definition}
The \emph{class map} is the $R$-linear map
$\toConj := \lmapDomain_R(\mk) : R[G] \to R[\Conj(G)]$, where $\mk : g\mapsto[g]$.
\end{definition}

\begin{lemma}[Action on basis]\label{lem:basis}
$\toConj(\single g\,r) = \single [g]\,r$.
\end{lemma}
\begin{proof}
Immediate from $\lmapDomain f\,(\single g\,r) = \single(f\,g)\,r$ with $f=\mk$.
\end{proof}

\begin{lemma}[Surjectivity]\label{lem:surj}
$\toConj$ is surjective.
\end{lemma}
\begin{proof}
Each class $q$ has a representative $g$ with $[g]=q$, so
$\toConj(\single g\,r) = \single q\,r$ by Lemma~\ref{lem:basis}; these generate
$R[\Conj(G)]$.
\end{proof}

\section{The commutator submodule is the kernel of the class map}

\begin{lemma}[Basic commutator identity]\label{lem:comm}
For all $a,b\in G$, $r\in R$,
$\single(ab)\,r - \single(ba)\,r \in [R[G],R[G]]$.
\end{lemma}
\begin{proof}
Set $X=\single a\,r$, $Y=\single b\,1$. By \eqref{eq:conv},
$XY-YX = \single(ab)\,r - \single(ba)\,r$, an additive commutator.
\end{proof}

\begin{lemma}[Conjugates differ by a commutator]\label{lem:conj}
If $u\sim v$ then $\single u\,r - \single v\,r \in [R[G],R[G]]$.
\end{lemma}
\begin{proof}
Choose $c$ with $c\,u\,c^{-1}=v$; put $a=c$, $b=u\,c^{-1}$. Then $ab=v$, $ba=u$,
and Lemma~\ref{lem:comm} together with closure under negation gives the claim.
\end{proof}

\begin{lemma}[Order invariance of $\toConj$]\label{lem:ord}
$\toConj(xy)=\toConj(yx)$ for all $x,y\in R[G]$.
\end{lemma}
\begin{proof}
By bilinearity reduce to $x=\single a\,1$, $y=\single b\,1$. By \eqref{eq:conv}
and Lemma~\ref{lem:basis}, both sides equal $\single[ab]\,1$ resp.
$\single[ba]\,1$; since $ab=a(ba)a^{-1}$ we have $ab\sim ba$, so by
\eqref{eq:mkeq} $[ab]=[ba]$. The general case follows by the bilinear induction
principle for $\mathtt{MonoidAlgebra}$ and distributivity.
\end{proof}

\begin{lemma}[Forward inclusion]\label{lem:fwd}
$[R[G],R[G]] \subseteq \ker(\toConj)$.
\end{lemma}
\begin{proof}
$\toConj(xy-yx)=0$ by Lemma~\ref{lem:ord}; $\ker(\toConj)$ is a submodule, hence
contains the span.
\end{proof}

\begin{lemma}[Reverse inclusion]\label{lem:rev}
$\ker(\toConj) \subseteq [R[G],R[G]]$.
\end{lemma}
\begin{proof}
Fix a section $\psi(g) := \out([g])$ of $\mk$, so $g\sim\psi(g)$ for all $g$. Let
$w\in\ker(\toConj)$, i.e. $\mapDomain\mk\,(w)=0$. By Lemma~\ref{lem:func} with
$\mk$ and $\out$,
\begin{equation}\label{eq:psizero}
\mapDomain\psi\,(w) = \mapDomain\out(\mapDomain\mk\,(w)) = \mapDomain\out(0) = 0.
\end{equation}
Expanding $w=\sum_{g\in\supp(w)}\single g\,(w\,g)$,
\[ w - \mapDomain\psi\,(w) = \sum_{g\in\supp(w)} \big(\single g\,(w\,g) - \single\psi(g)\,(w\,g)\big), \]
and each summand lies in $[R[G],R[G]]$ by Lemma~\ref{lem:conj}, so the finite sum
does too. With \eqref{eq:psizero}, $w\in[R[G],R[G]]$. Every sum ranges only over
the finite support of $w$; finiteness of $G$ is never used.
\end{proof}

\begin{theorem}[Commutator submodule equals kernel]\label{thm:eqker}
$[R[G],R[G]] = \ker(\toConj)$.
\end{theorem}
\begin{proof}
Antisymmetry from Lemmas~\ref{lem:fwd} and \ref{lem:rev}.
\end{proof}

\section{The main equivalence}

\begin{theorem}[Main theorem]\label{thm:main}
For any commutative ring $R$ and any group $G$,
\[ \HH_0(R[G]) \simeq_R R[\Conj(G)]. \]
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:eqker} the defining submodule of
$\HH_0(R[G]) = R[G]/[R[G],R[G]]$ is $\ker(\toConj)$. The first isomorphism
theorem gives $R[G]/\ker(\toConj) \simeq_R \image(\toConj) = R[\Conj(G)]$, the
last equality by surjectivity (Lemma~\ref{lem:surj}).
\end{proof}

\begin{corollary}[Finite case]\label{cor:finite}
If $G$ is finite, $\HH_0(R[G])$ is free of rank $|\Conj(G)|$.
\end{corollary}
\begin{proof}
Specialize Theorem~\ref{thm:main}; for finite $G$, $R[\Conj(G)]$ is free of rank
$|\Conj(G)|$.
\end{proof}

\section{Algorithms}

\begin{algorithm}[Conjugacy-class partition]
Given finite $G$ as a multiplication table, compute $\Conj(G)$ by orbit
enumeration under $u\mapsto c\,u\,c^{-1}$, in $O(|G|^2)$ group operations. The
number of classes is $\dim_R\HH_0(R[G])$.
\end{algorithm}

\begin{algorithm}[Reduction to $\HH_0$ coordinates]
For $w=\sum_g r_g\,g$, its image in $\HH_0(R[G]) = R[\Conj(G)]$ is
\[ \toConj(w) = \sum_{[c]\in\Conj(G)}\Big(\sum_{g\in[c]} r_g\Big)[c], \]
the explicit universal trace, computed in $O(|G|)$ after partitioning.
\end{algorithm}

\section{Applications}

\begin{enumerate}
\item \textbf{Characters are class functions.} Any trace $\tau:\mathbb{C}[G]\to V$
factors through $\HH_0(\mathbb{C}[G]) = \mathbb{C}[\Conj(G)]$
(Proposition~\ref{prop:univ}, Theorem~\ref{thm:main}), hence is constant on
classes.
\item \textbf{Counting irreducibles.} For finite $G$ over $\mathbb{C}$, the number
of irreducibles equals $\dim\HH_0(\mathbb{C}[G]) = |\Conj(G)|$.
\item \textbf{The class algebra.} When $G$ is finite, $\HH_0$ inherits a
commutative product realizing the class-sum algebra with structure constants
$a_{ij}^k$; the module equivalence here is its substrate.
\end{enumerate}

\section{Discussion}

The proof isolates one nontrivial idea --- the commutator $XY-YX$ with
$X=\single a\,r$, $Y=\single b\,1$ realizes $\single(ab)\,r \equiv \single(ba)\,r$
--- and derives $[R[G],R[G]]=\ker(\toConj)$ via a representative collapse using a
section $\psi$ of $\mk$ and functoriality of $\mapDomain$. The reverse inclusion
is the delicate step, and its proof shows finiteness is dispensable: it touches
only the finite support of $w$.

\section{Future directions}

\begin{enumerate}
\item \textbf{Ring structure via the class-sum algebra.} For finite $G$,
transport the $\HH_0$ multiplication and verify it reproduces the class-algebra
structure constants $[C_i][C_j]=\sum_k a_{ij}^k[C_k]$.
\item \textbf{Finiteness removable in low-degree HH.} Conjecturally
$\HH_0(R[G])$ is free on $\Conj(G)$ for all $G$ and $\HH_1(R[G])$ decomposes by
conjugacy class; the degree-0 technique is a template for the bar complex.
\item \textbf{Functoriality.} A surjection $\varphi:G\twoheadrightarrow H$ should
induce a surjection $\HH_0(R[G])\to\HH_0(R[H])$ compatible with
$\Conj(G)\to\Conj(H)$, since $\mk$ and $\lmapDomain$ are natural.
\item \textbf{Trace characterization.} Over a field of characteristic zero,
$K[G]\to\HH_0(K[G])\simeq K[\Conj(G)]$ should be the universal trace.
\end{enumerate}

\section{Conclusion}

We gave a formally verified proof that $\HH_0(R[G]) \simeq_R R[\Conj(G)]$ for
arbitrary group $G$ and commutative ring $R$, identifying the universal home of
traces with one coordinate per conjugacy class, explaining why characters are
class functions, and yielding a constructive computation of $\HH_0$. The removal
of finiteness illustrates how a careful argument reveals which hypotheses truly
do the work.

\end{document}

