function CONJUGACY_CLASSES(order, mul, inv):
    seen ← ∅
    classes ← []
    for u in 0 .. order-1:
        if u ∈ seen: continue
        orbit ← { mul[mul[c][u]][inv[c]] : c in 0 .. order-1 }
        append orbit to classes
        seen ← seen ∪ orbit
    return classes

function TO_CONJ_COORDINATES(coeffs, classes):
    coords ← []
    for cls in classes:
        s ← 0
        for g in cls:
            s ← s + coeffs.get(g, 0)
        append s to coords
    return coords
